import json,datetime
from pathlib import Path
root=Path('outputs/kings-site');p=root/'content/events.json';events=json.loads(p.read_text());images={r['n']:r for r in json.load(open('work/kings-live-audit/images.json'))}
S='https://kingsofkingsinternational.com/studio/';C='https://kingsofkingsinternational.com/reggae-events/canada/'
def add(slug,title,date,city,venue,address,n,names,desc,source=S):
 if any(e['slug']==slug for e in events):return
 events.append(dict(slug=slug,title=title,date=date,display=datetime.date.fromisoformat(date).strftime('%d %b %Y').upper(),city=city,venue=venue,address=address,image=images[n]['image'],performers=names.split('|') if names else [],description=desc,status='past',source_url=source,source=images[n]['url']))
add('sizzla-rise-to-the-occasion-2026','Sizzla Youth Foundation — Rise to the Occasion','2026-08-30','Scarborough, Ontario','Bass Lounge','91 Rylander Boulevard, Scarborough, Ontario',47,'Sizzla Kalonji','The live site advertised the second annual Sizzla Youth Foundation fireside chat and community conversation, supporting the foundation and Urban Rez Community Mobile Unit.')
for slug,date,city,venue,address,n in [('montreal','2026-05-29','Montréal, Québec','The Caribbean Food Factory','Montréal, Québec',51),('toronto','2026-05-30','Toronto, Ontario','Jamaican Canadian Association','995 Arrow Road, North York, Ontario',53)]:
 add('31st-anniversary-'+slug+'-2026','Kings of Kings 31st Anniversary — '+city.split(',')[0],date,city,venue,address,n,'Tony Matterhorn|Iley Dread|Stone Love','The 31st anniversary celebration connected sound system culture with an Iley Dread album launch. The original listing names Tony Matterhorn, Iley Dread and Stone Love.')
