add('magnum-christmas-extravaganza-2008','Magnum Christmas Reggae Extravaganza','2008-12-25','Black River, Jamaica','Independence Park','Black River, St. Elizabeth, Jamaica',82,'','G.T. Promotions’ Christmas event poster is preserved in the Kings website gallery. Its presence in the archive does not establish Kings as the producer.','https://kingsofkingsinternational.com/gallery/')
# Preserve additions and all source references without overwriting original supplied material.
p.write_text(json.dumps(events,indent=2,ensure_ascii=False)+'\n')
# Undated, conflicting or promotional-only material is preserved separately, never assigned invented calendar dates.
extra=[(4,'Reggae 55th Anniversary — Ambassador Award Show','Advertised August 25, 2024 in Toronto. The same advance poster also mentions Montréal on August 23 and Ottawa on August 24. Venue and final programme are not supplied; names below the headline are award nominees, not a confirmed performance lineup.'),(60,'Grateful Vibes — Awards Presentation','Advertised October 13 at the JCA with I-Octane. The website text says 2004, while its 2024 placement and Sunday wording conflict with that year. The year is left unresolved.'),(64,'Montréal Reggae Extravaganza','Advertised August 23 at MTELUS, 59 St Catherine Street East. No year is printed on this flyer; another advance poster mentions a Montréal date in 2024.'),(84,'Purple N Grey Summer Mix','I-Octane and Stone Love at EB Club Lounge, Montréal, August 13. The printed year is not fully legible, so no year is assigned.'),(85,'Rastafari Awareness Day','The Ethiopian World Federation 25th anniversary poster lists March 1, 2008 at South Birmingham College auditorium. Retained as gallery material; no Kings production role is assumed.'),(83,'Irie Jamboree ’06','Historical festival advertisement found in the Kings gallery. The visible cover does not provide a complete date or venue.'),(65,'Mavado & Friends','Skip2Fame’s November 5, 2026 Scotiabank Arena poster, found in the gallery. Preserved as an externally promoted listing.'),(76,'Lover’s Holiday — CD Release Party','December 19 at the Annex WreckRoom. The year is not printed; preserved alongside the supplied release showcase artwork.'),(6,'Wonderful Vibrations — Canada','2024 regional campaign artwork, rather than an additional dated show.'),(11,'Wonderful Vibrations — Germany','2024 regional campaign artwork without a confirmed calendar date.'),(12,'Wonderful Vibrations — Jamaica','2024 regional campaign artwork. A 2023 announcement proposed a Jamaican event, with date and artists still to be announced.')]
(root/'content/live-event-posters.json').write_text(json.dumps([dict(title=t,description=d,image=images[n]['image'],source_url=images[n]['page'],original_image=images[n]['url']) for n,t,d in extra],indent=2,ensure_ascii=False)+'\n')
print('Event collection:',len(events),'dated entries; additional poster records:',len(extra))
